def clamp(value, low, high):
    return min(high, max(low, value))

def wheel_speeds(v, omega):
    half = WHEELBASE_M / 2.0
    return v - omega * half, v + omega * half

def body_command(distance_cm, battery_volts):
    if battery_volts <= CUTOFF_V:
        return 0.0, 0.0
    if distance_cm < STOP_CM:
        return 0.0, 1.2
    if distance_cm < SLOW_CM:
        return 0.15, 0.0
    return 0.35, 0.0

