    v, omega = body_command(distance_cm, battery_volts)
    left, right = wheel_speeds(v, omega)
    return clamp(left, -MAX_WHEEL_MS, MAX_WHEEL_MS), clamp(right, -MAX_WHEEL_MS, MAX_WHEEL_MS)

