import math

class Robot:
    MAX_SPEED = 0.45

    def __init__(self, name):
        self.name = name
        self.theta = 0.0
        self._speed = 0.0

    def set_speed(self, value):
        clamped = min(self.MAX_SPEED, max(-self.MAX_SPEED, value))
        if clamped != value:
            print(f"speed {value:.2f} clamped to {clamped:.2f}")
        self._speed = clamped

    def turn(self, delta_rad):
        self.theta = self.wrap(self.theta + delta_rad)

    def wrap(self, a):
        while a > math.pi:
            a = a - 2 * math.pi
        while a < -math.pi:
            a = a + 2 * math.pi
        return a

