        self.index = 0

    def read(self):
        value = self.readings[self.index % len(self.readings)]
        self.index = self.index + 1
        return value

class Rover:
    STOP_CM = 20.0

    def __init__(self, name, sensor):
        self.name = name
        self.left = Motor("left")
        self.right = Motor("right")
