MAX_ACCEL = 40.0

def checksum(payload):
    acc = 0
    for ch in payload:
        acc = acc ^ ord(ch)
    return acc

def build(payload):
    return (payload + "*" + f"{checksum(payload):02X}" + "\r\n").encode("ascii")

def parse_frame(raw, stats):
    text = raw.decode("ascii", errors="ignore").strip()
    if "*" not in text:
        stats["no_checksum"] = stats.get("no_checksum", 0) + 1
        return None
    payload, _, given = text.partition("*")
    try:
        if checksum(payload) != int(given, 16):
            stats["bad_checksum"] = stats.get("bad_checksum", 0) + 1
            return None
    except ValueError:
        stats["bad_checksum"] = stats.get("bad_checksum", 0) + 1
        return None
    parts = payload.split(",")
    if len(parts) != 4 or parts[0] != "IMU":
        stats["bad_shape"] = stats.get("bad_shape", 0) + 1
        return None
    try:
        ax, ay, az = float(parts[1]), float(parts[2]), float(parts[3])
    except ValueError:
        stats["non_numeric"] = stats.get("non_numeric", 0) + 1
        return None
    if max(abs(ax), abs(ay), abs(az)) > MAX_ACCEL:
        stats["out_of_range"] = stats.get("out_of_range", 0) + 1
        return None
    return ax, ay, az

frames = [
    build("IMU,0.12,-0.03,9.81"),
    build("IMU,0.09,-0.01,9.79"),
    b"IMU,0.10,0.00,9.80\r\n",
    build("IMU,0.10,0.00"),
    build("IMU,0.10,x,9.80"),
    build("IMU,0.10,0.00,988.0"),
]

stats = {}
accepted = 0
