import math

class World:
    def __init__(self, width_m, height_m, obstacles):
        self.width_m = width_m
        self.height_m = height_m
        self.obstacles = obstacles

    def free(self, x, y):
        if not 0.0 <= x <= self.width_m or not 0.0 <= y <= self.height_m:
            return False
        for ox, oy, r in self.obstacles:
            if math.hypot(x - ox, y - oy) <= r:
                return False
        return True

class Rangefinder:
    BEAM_DEG = (-60.0, -30.0, -10.0, 0.0, 10.0, 30.0, 60.0)
    MAX_RANGE_M = 2.0
    STEP_M = 0.01

    def __init__(self, world):
        self.world = world

    def ray(self, x, y, heading):
        d = 0.0
        while d < self.MAX_RANGE_M:
            d = d + self.STEP_M
            px = x + d * math.cos(heading)
            py = y + d * math.sin(heading)
            if not self.world.free(px, py):
                return d
        return self.MAX_RANGE_M

    def scan(self, x, y, theta):
        return [self.ray(x, y, theta + math.radians(b)) for b in self.BEAM_DEG]

world = World(4.0, 3.0, [(2.0, 1.5, 0.30), (3.0, 0.8, 0.25)])
sensor = Rangefinder(world)

for pose in ((1.0, 1.5, 0.0), (2.6, 0.4, math.radians(45.0))):
    ranges = sensor.scan(pose[0], pose[1], pose[2])
